<div class="page-title clearfix"><h1><?php echo esc($transfer->folio); ?> — <?php echo esc($transfer->origin_name.' → '.$transfer->destination_name); ?></h1><a href="<?php echo get_uri('warehouses/transfers'); ?>" class="btn btn-default float-end">Volver</a></div><div class="row"><div class="col-md-9"><div class="card"><div class="card-header"><ul class="nav nav-tabs card-header-tabs"><li class="nav-item"><a class="nav-link active" data-bs-toggle="tab" href="#tr-products">Productos</a></li><li class="nav-item"><a class="nav-link" data-bs-toggle="tab" href="#tr-receipts">Recepciones</a></li><li class="nav-item"><a class="nav-link" data-bs-toggle="tab" href="#tr-events">Eventos</a></li><li class="nav-item"><a class="nav-link" data-bs-toggle="tab" href="#tr-diffs">Incidencias</a></li></ul></div><div class="card-body tab-content"><div id="tr-products" class="tab-pane active"><table class="table"><thead><tr><th>Producto</th><th>Enviado</th><th>Recibido</th><th>Pendiente</th></tr></thead><tbody><?php foreach($lines as $l): ?><tr><td><?php echo esc($l->internal_code.' - '.$l->product_name); ?></td><td><?php echo esc(to_decimal_format($l->quantity_sent)); ?></td><td><?php echo esc(to_decimal_format($l->quantity_received)); ?></td><td><b><?php echo esc(to_decimal_format($l->quantity_pending)); ?></b></td></tr><?php endforeach; ?></tbody></table></div><div id="tr-receipts" class="tab-pane"><table class="table"><thead><tr><th>Fecha</th><th>Movimiento</th><th>Usuario</th><th>Notas</th></tr></thead><tbody><?php foreach($receipts as $r): ?><tr><td><?php echo esc($r->receipt_date); ?></td><td><a href="<?php echo get_uri('warehouses/movements/view/'.$r->warehouse_movement_id); ?>"><?php echo esc($r->movement_folio); ?></a></td><td><?php echo esc($r->user_name?:'-'); ?></td><td><?php echo esc($r->notes?:'-'); ?></td></tr><?php endforeach; ?></tbody></table></div><div id="tr-events" class="tab-pane"><div class="list-group"><?php foreach($events as $e): ?><div class="list-group-item"><b><?php echo esc($e->event_type); ?></b> · <?php echo esc($e->event_at); ?> · <?php echo esc($e->user_name?:'-'); ?><br><?php echo esc($e->notes?:''); ?></div><?php endforeach; ?></div></div><div id="tr-diffs" class="tab-pane"><?php if(!$differences): ?><div class="text-muted">No hay incidencias.</div><?php endif;foreach($differences as $d): ?><div class="alert alert-warning"><b><?php echo esc($d->product_name); ?></b>: <?php echo esc(to_decimal_format($d->quantity_difference)); ?><br><?php echo esc($d->reason); ?></div><?php endforeach; ?></div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><h5>Estado</h5><p><b><?php echo esc($transfer->status); ?></b></p><p>Origen: <?php echo esc($transfer->origin_name); ?><br>Destino: <?php echo esc($transfer->destination_name); ?><br>Guía: <?php echo esc($transfer->tracking_number?:'-'); ?><br>Paquetería: <?php echo esc($transfer->carrier?:'-'); ?></p><?php if(in_array($transfer->status,['draft','prepared'],true)&&$can_dispatch): ?><button id="dispatch-transfer" class="btn btn-primary w-100 mb10">Despachar</button><?php endif; ?><?php if(in_array($transfer->status,['in_transit','partially_received'],true)&&$can_receive): echo modal_anchor(get_uri('warehouses/transfers/'.$transfer->id.'/receive-form'),'Recibir',['class'=>'btn btn-success w-100 mb10']); ?><hr><?php echo form_open(get_uri('warehouses/transfers/'.$transfer->id.'/close-difference'),['id'=>'difference-form']);echo csrf_field(); ?><label>Cerrar faltante con incidencia</label><textarea name="reason" class="form-control" placeholder="Motivo obligatorio"></textarea><button class="btn btn-warning w-100 mt10">Cerrar con diferencia</button><?php echo form_close();endif; ?><?php if($can_logistics): ?><hr><?php echo form_open(get_uri('warehouses/transfers/'.$transfer->id.'/logistics'),['id'=>'logistics-form']);echo csrf_field(); ?><label>Paquetería</label><input class="form-control" name="carrier" value="<?php echo esc($transfer->carrier); ?>"><label>Guía</label><input class="form-control" name="tracking_number" value="<?php echo esc($transfer->tracking_number); ?>"><label>Llegada estimada</label><input type="datetime-local" class="form-control" name="estimated_arrival_at" value="<?php echo $transfer->estimated_arrival_at?date('Y-m-d\TH:i',strtotime($transfer->estimated_arrival_at)):''; ?>"><button class="btn btn-default w-100 mt10">Actualizar logística</button><?php echo form_close();endif; ?></div></div></div></div><script>$('#dispatch-transfer').on('click',function(){if(confirm('¿Despachar este traspaso? El origen se descontará y quedará en tránsito.'))$.post('<?php echo get_uri('warehouses/transfers/'.$transfer->id.'/dispatch'); ?>',{'<?php echo csrf_token(); ?>':'<?php echo csrf_hash(); ?>'}).done(function(){location.reload();}).fail(function(x){appAlert.error(x.responseJSON&&x.responseJSON.message||'No fue posible despachar.');});});$('#difference-form,#logistics-form').appForm({onSuccess:function(){location.reload();}});</script>
